1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10	
11		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
12	)
13	
14	// replicateInput 是 replicate 子命令从标准输入读取的 JSON。
15	//
16	// log、requests 以及请求内 entries 是允许在同一对象中重复出现的数组字段，约定
17	// 后者生效。encoding/json 把重复出现的数组解到同一个非 nil 切片时，只会按下标
18	// 覆盖既有元素：后一份数组较短时尾部残留旧元素，元素省略的字段（command、
19	// index、term）也会从相同位置的旧元素继承，等于让用户给出的后一份日志借用了
20	// 前一份的内容。因此这三个数组都用整体替换的包装类型（replicateInputLog 等）
21	// 解码：每一次出现都解进一份全新的切片并整体替换，最后一份数组是什么就保留
22	// 什么，元素省略的数值按默认 0、省略的命令按空字符串解释。
23	type replicateInput struct {
24		CurrentTerm    int                    `json:"currentTerm"`
25		CommittedIndex int                    `json:"committedIndex"`
26		Log            replicateInputLog      `json:"log"`
27		ApplyKV        bool                   `json:"applyKV"`
28		Requests       replicateInputRequests `json:"requests"`
29	}
30	
31	// replicateInputLog 是根对象的 log 字段：重复出现时最后一份数组整体替换。
32	type replicateInputLog []mevwatch.LogEntry
33	
34	func (l *replicateInputLog) UnmarshalJSON(data []byte) error {
35		return unmarshalLastWinsArray(data, (*[]mevwatch.LogEntry)(l))
36	}
37	
38	// replicateInputRequest 与 mevwatch.AppendRequest 字段相同，区别只是 entries
39	// 也走整体替换解码。
40	type replicateInputRequest struct {
41		Term         int                   `json:"term"`
42		PrevLogIndex int                   `json:"prevLogIndex"`
43		PrevLogTerm  int                   `json:"prevLogTerm"`
44		Entries      replicateInputEntries `json:"entries"`
45		LeaderCommit int                   `json:"leaderCommit"`
46	}
47	
48	// replicateInputRequests 是根对象的 requests 字段：重复出现时最后一份数组
49	// 整体替换，而不是把后一份请求按下标并进前一份。
50	type replicateInputRequests []replicateInputRequest
51	
52	func (r *replicateInputRequests) UnmarshalJSON(data []byte) error {
53		return unmarshalLastWinsArray(data, (*[]replicateInputRequest)(r))
54	}
55	
56	// replicateInputEntries 是单个请求内的 entries 字段：同一请求对象里重复
57	// 出现时，最后一份条目数组整体替换。
58	type replicateInputEntries []mevwatch.LogEntry
59	
60	func (e *replicateInputEntries) UnmarshalJSON(data []byte) error {
61		return unmarshalLastWinsArray(data, (*[]mevwatch.LogEntry)(e))
62	}
63	
64	// unmarshalLastWinsArray 把一次数组字段出现解进一份全新的切片，并用它整体
65	// 替换 dst。它必须先解进局部切片而不能直接解到 dst：encoding/json 对“非 nil
66	// 现有切片 + 重复数组键”只做下标覆盖，短数组的尾部与元素内省略的字段都会
67	// 残留上一次出现的内容。null 与既有行为一致，把目标置为空切片（nil）。
68	func unmarshalLastWinsArray[T any](data []byte, dst *[]T) error {
69		var next []T
70		if err := json.Unmarshal(data, &next); err != nil {
71			return err
72		}
73		*dst = next
74		return nil
75	}
76	
77	// runReplicate 从标准输入读取一份 JSON（初始状态 + 顺序到达的复制请求），
78	// 把逐次接收结果与最终日志作为一份 JSON 写到标准输出。
79	// 初始状态非法或 JSON 无法解析时，以非零退出码和明确错误结束。
80	func runReplicate() int {
81		return runReplicateIO(os.Stdin, os.Stdout, os.Stderr)
82	}
83	
84	func runReplicateIO(stdin io.Reader, stdout, stderr io.Writer) int {
85		data, err := io.ReadAll(stdin)
86		if err != nil {
87			fmt.Fprintf(stderr, "replicate: read stdin: %v\n", err)
88			return 1
89		}
90		var syntaxCheck interface{}
91		if err := json.Unmarshal(data, &syntaxCheck); err != nil {
92			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
93			return 1
94		}
95		// 已识别的数值字段被显式写成 null 时，类型化解码会静默当成零值继续
96		// 处理（例如 committedIndex 为 null 被当成“尚未提交”），必须在读取
97		// 输入阶段把整份输入作为字段类型错误拒绝。检查直接扫描 JSON token
98		// 而不是先解进 map：map 解码对重复键只保留最后一次出现，既会漏掉
99		// 写在数字前面的 null，也会让后出现的 log/requests/entries 数组盖掉
100		// 前一份数组，因此重复键的每一次出现都必须单独检查。
101		if path := nullNumericFieldPath(data); path != "" {
102			fmt.Fprintf(stderr, "replicate: invalid field type: %s must be a number, got null\n", path)
103			return 1
104		}
105		var input replicateInput
106		if err := json.Unmarshal(data, &input); err != nil {
107			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
108			return 1
109		}
110		// 三个数组经整体替换解码后再逐元素转成库类型：转换只按最后一份数组的实际
111		// 内容进行，不携带任何同名前序数组的条目字段。
112		initialLog := append([]mevwatch.LogEntry(nil), input.Log...)
113		requests := make([]mevwatch.AppendRequest, len(input.Requests))
114		for i, req := range input.Requests {
115			requests[i] = mevwatch.AppendRequest{
116				Term:         req.Term,
117				PrevLogIndex: req.PrevLogIndex,
118				PrevLogTerm:  req.PrevLogTerm,
119				Entries:      append([]mevwatch.LogEntry(nil), req.Entries...),
120				LeaderCommit: req.LeaderCommit,
121			}
122		}
123		output, err := mevwatch.ReplicateWithOptions(mevwatch.InitialState{
124			CurrentTerm:    input.CurrentTerm,
125			CommittedIndex: input.CommittedIndex,
126			Log:            initialLog,
127		}, requests, mevwatch.ReplicateOptions{ApplyKV: input.ApplyKV})
128		if err != nil {
129			fmt.Fprintf(stderr, "replicate: %v\n", err)
130			return 1
131		}
132		encoded, err := json.MarshalIndent(output, "", "  ")
133		if err != nil {
134			fmt.Fprintf(stderr, "replicate: encode output JSON: %v\n", err)
135			return 1
136		}
137		fmt.Fprintln(stdout, string(encoded))
138		return 0
139	}
140	
141	// objectSchema 描述某一层次对象里已识别的字段：numerics 是显式写成 null 时
142	// 必须拒绝整份输入的数值字段（标准拼写），arrays 是元素为对象的数组字段及其
143	// 元素层次。字段名识别与 encoding/json 一致，只改变字母大小写的写法同样命中；
144	// 错误位置始终使用这里的标准拼写而不是输入里的大小写变体。根状态、复制请求
145	// 与日志条目共用同一套扫描逻辑，区别只在下面三份 schema。
146	type objectSchema struct {
147		numerics []string
148		arrays   []arrayField
149	}
150	
151	// arrayField 是一个已识别的对象数组字段：name 为标准字段名，elem 为数组元素
152	// 所在层次的 schema。
153	type arrayField struct {
154		name string
155		elem *objectSchema
156	}
157	
158	var (
159		// 日志条目层次：log[i] 与 requests[r].entries[i] 是同一种对象。
160		entryObjectSchema = &objectSchema{numerics: []string{"index", "term"}}
161		// 复制请求层次：数值字段外还嵌套 entries 条目数组。
162		requestObjectSchema = &objectSchema{
163			numerics: []string{"term", "prevLogIndex", "prevLogTerm", "leaderCommit"},
164			arrays:   []arrayField{{name: "entries", elem: entryObjectSchema}},
165		}
166		// 根输入层次：初始状态的数值字段外还嵌套 log 与 requests 两个数组。
167		rootObjectSchema = &objectSchema{
168			numerics: []string{"currentTerm", "committedIndex"},
169			arrays: []arrayField{
170				{name: "log", elem: entryObjectSchema},
171				{name: "requests", elem: requestObjectSchema},
172			},
173		}
174	)
175	
176	// numericName 在 key 命中本层次某个已识别数值字段时返回它的标准拼写。
177	func (s *objectSchema) numericName(key string) (string, bool) {
178		for _, name := range s.numerics {
179			if strings.EqualFold(key, name) {
180				return name, true
181			}
182		}
183		return "", false
184	}
185	
186	// arrayField 在 key 命中本层次某个已识别数组字段时返回它的定义（含标准拼写）。
187	func (s *objectSchema) arrayField(key string) (arrayField, bool) {
188		for _, field := range s.arrays {
189			if strings.EqualFold(key, field.name) {
190				return field, true
191			}
192		}
193		return arrayField{}, false
194	}
195	
196	// nullNumericFieldPath 扫描整份输入 JSON 的 token 流，查找第一个被显式写成
197	// null 的已识别数值字段，返回它的完整位置；没有时返回空串。检查范围是初始
198	// 状态（currentTerm、committedIndex、log[i].index、log[i].term）与每条复制
199	// 请求（term、prevLogIndex、prevLogTerm、leaderCommit 及 entries[j].index、
200	// entries[j].term）；请求与条目下标从 0 开始，例如第二条请求的提交位置记为
201	// requests[1].leaderCommit。
202	//
203	// 必须扫描 token 而不能先解进 map[string]interface{}：map 解码遇到重复键只
204	// 保留最后一次出现的值。{"currentTerm":null,"currentTerm":1} 里先出现的
205	// null 会因此漏检；log/requests/entries 自身重复出现时，前一份数组里的数值
206	// null 也会被后一份数组盖掉。token 流保留键的每一次出现，重复字段无论 null
207	// 在数字之前还是之后、数组字段重复多少次、拼写是否只改变大小写，都逃不过
208	// 检查。数组字段本身为 null、未知键（含未知对象里的同名键）里的 null 不在
209	// 检查范围内，扫描时只按结构识别已知字段，不进入其他对象与数组。
210	func nullNumericFieldPath(data []byte) string {
211		dec := json.NewDecoder(bytes.NewReader(data))
212	
213		// 取根对象的第一个 token；输入不是对象或 JSON 非法时没有可报告的数值
214		// 字段位置，交由随后的类型化解码产出既有的解析错误。
215		tok, err := dec.Token()
216		if err != nil || tok != json.Delim('{') {
217			return ""
218		}
219		return scanObjectFields(dec, rootObjectSchema, "")
220	}
221	
222	// scanObjectFields 扫描一个已读入起始 '{' 的对象的字段流，prefix 是该对象
223	// 的位置前缀（根对象为空，其余层次以 "." 结尾，如 "requests[1]."）。每个键
224	// 按所在层次的 schema 分派：已识别数值字段检查是否写成 null，已识别数组字段
225	// 递归扫描元素，其余键的值整体跳过。返回第一个数值 null 的完整位置。
226	func scanObjectFields(dec *json.Decoder, schema *objectSchema, prefix string) string {
227		for dec.More() {
228			key, ok := decodeKey(dec)
229			if !ok {
230				return ""
231			}
232			if name, ok := schema.numericName(key); ok {
233				if nullScalarPath(dec) {
234					return prefix + name
235				}
236				continue
237			}
238			if field, ok := schema.arrayField(key); ok {
239				if path := scanObjectArray(dec, field.elem, prefix+field.name); path != "" {
240					return path
241				}
242				continue
243			}
244			skipValue(dec)
245		}
246		return ""
247	}
248	
249	// scanObjectArray 扫描一个对象数组字段的完整 token 流（数组字段重复出现时由
250	// 调用方对每一份数组分别调用），arrayPath 是数组自身的位置（如 "log" 或
251	// "requests[r].entries"），返回第一个数值 null 的完整位置。
252	func scanObjectArray(dec *json.Decoder, elem *objectSchema, arrayPath string) string {
253		tok, err := dec.Token()
254		if err != nil {
255			return ""
256		}
257		if tok != json.Delim('[') {
258			// 数组字段本身为 null 或其他类型（如被写成对象）：沿用既有处理，
259			// 类型错误由随后的类型化解码按既有格式报告。这里必须把整个值消费
260			// 完——起始分隔符已经读出，若就此返回，调用方的循环会落到对象内部，
261			// 把其中的 term/index 等字段当成外层已识别字段，其后的真实数值
262			// null 也会被漏检。
263			if d, ok := tok.(json.Delim); ok {
264				skipRest(dec, d)
265			}
266			return ""
267		}
268		for i := 0; dec.More(); i++ {
269			tok, err := dec.Token()
270			if err != nil {
271				return ""
272			}
273			if tok != json.Delim('{') {
274				// 非对象元素不可能含已识别字段；若它本身是容器仍要消费完整。
275				if d, ok := tok.(json.Delim); ok {
276					skipRest(dec, d)
277				}
278				continue
279			}
280			prefix := fmt.Sprintf("%s[%d].", arrayPath, i)
281			if path := scanObjectFields(dec, elem, prefix); path != "" {
282				return path
283			}
284			if _, err := dec.Token(); err != nil { // 元素对象的 '}'
285				return ""
286			}
287		}
288		if _, err := dec.Token(); err != nil { // 数组的 ']'
289			return ""
290		}
291		return ""
292	}
293	
294	// decodeKey 读取并断言下一个 token 是对象键。
295	func decodeKey(dec *json.Decoder) (string, bool) {
296		tok, err := dec.Token()
297		if err != nil {
298			return "", false
299		}
300		key, ok := tok.(string)
301		return key, ok
302	}
303	
304	// nullScalarPath 消费一个已识别数值字段的值 token 流，报告该次出现是否被
305	// 显式写成 null。值为对象或数组时整体跳过（结构异常的输入留给类型化解码
306	// 报告既有错误）。
307	func nullScalarPath(dec *json.Decoder) bool {
308		tok, err := dec.Token()
309		if err != nil {
310			return false
311		}
312		if tok == nil {
313			return true
314		}
315		if d, ok := tok.(json.Delim); ok {
316			skipRest(dec, d)
317		}
318		return false
319	}
320	
321	// skipValue 读取并消费一个完整的 JSON 值（标量或容器）。
322	func skipValue(dec *json.Decoder) {
323		tok, err := dec.Token()
324		if err != nil {
325			return
326		}
327		if d, ok := tok.(json.Delim); ok {
328			skipRest(dec, d)
329		}
330	}
331	
332	// skipRest 消费一个容器剩余的 token 流，open 是已经读出的起始分隔符；
333	// 起始分隔符不是 '{' / '[' 时无需消费，直接返回。
334	func skipRest(dec *json.Decoder, open json.Delim) {
335		if open != '{' && open != '[' {
336			return
337		}
338		depth := 1
339		for depth > 0 {
340			tok, err := dec.Token()
341			if err != nil {
342				return
343			}
344			if d, ok := tok.(json.Delim); ok {
345				switch d {
346				case '{', '[':
347					depth++
348				case '}', ']':
349					depth--
350				}
351			}
352		}
353	}
